\set ON_ERROR_STOP on
BEGIN READ ONLY;SET LOCAL statement_timeout='10s';
DO $$ DECLARE f jsonb;prior jsonb;order_ids uuid[];shift_ids uuid[];BEGIN
 ASSERT current_database()='vinpoker_fnb719_gate_local' AND host(inet_server_addr())='127.0.0.1' AND inet_server_port()=55441;
 ASSERT current_setting('data_directory')='/tmp/vinpoker-sol-local-20261016-0e79a729/data';
 ASSERT (SELECT shobj_description(oid,'pg_database') FROM pg_database WHERE datname=current_database())='VINPOKER_FNB719_OWNED_LOCAL_CLONE_SOURCE_vinpoker_ops_cash115_qualified_c_HEAD_ef6a26948';
 SELECT fixture INTO STRICT f FROM floor_private.fnb723_fixture;
 ASSERT f->>'test_only'='true' AND f->>'state'='qualified';
 SELECT array_agg(value::uuid ORDER BY ordinality) INTO order_ids FROM jsonb_array_elements_text(f->'orders') WITH ORDINALITY;
 SELECT array_agg(value::uuid ORDER BY ordinality) INTO shift_ids FROM jsonb_array_elements_text(f->'shifts') WITH ORDINALITY;
 ASSERT cardinality(order_ids)=5 AND cardinality(shift_ids)=6;
 ASSERT (SELECT count(*)=100 FROM public.game_tables WHERE club_id=(f->>'club')::uuid);
 ASSERT (SELECT on_hand=16 FROM public.fnb_ingredients WHERE id=(f->>'ingredient')::uuid);
 ASSERT (SELECT count(*)=6 AND sum(delta)=-4 FROM public.fnb_stock_movements WHERE ref_id=ANY(order_ids));
 ASSERT (SELECT count(*)=6 AND sum((status='closed')::int)=5 AND sum((status='open')::int)=1 FROM public.fnb_cashier_shifts WHERE club_id=(f->>'club')::uuid);
 ASSERT (SELECT expected_cash_vnd=5000 AND variance_vnd=0 FROM public.fnb_cashier_shifts WHERE id=shift_ids[1]);
 ASSERT (SELECT expected_cash_vnd=0 FROM public.fnb_cashier_shifts WHERE id=shift_ids[2]);
 ASSERT (SELECT expected_cash_vnd=0 AND frozen_report->>'sales_vnd'='5000' AND frozen_report->>'refunds_vnd'='5000' FROM public.fnb_cashier_shifts WHERE id=shift_ids[3]);
 ASSERT (SELECT expected_cash_vnd=5000 AND frozen_report->>'refunds_vnd'='0' FROM public.fnb_cashier_shifts WHERE id=shift_ids[4]);
 ASSERT (SELECT expected_cash_vnd=-5000 AND variance_vnd=5000 FROM public.fnb_cashier_shifts WHERE id=shift_ids[5]);
 ASSERT (SELECT count(*)=1 FROM floor_private.fnb_shift_order_events722 WHERE order_id=order_ids[1] AND shift_id=shift_ids[1] AND kind='sale');
 ASSERT (SELECT count(*)=1 FROM floor_private.fnb_shift_order_events722 WHERE order_id=order_ids[2] AND shift_id IS NULL AND kind='sale');
 ASSERT (SELECT count(*)=2 FROM floor_private.fnb_shift_order_events722 WHERE order_id=order_ids[3] AND shift_id=shift_ids[3]);
 ASSERT (SELECT count(*)=1 FROM floor_private.fnb_shift_order_events722 WHERE order_id=order_ids[4] AND shift_id=shift_ids[5] AND kind='refund');
 ASSERT (SELECT status='pending' AND paid_at IS NULL FROM public.fnb_orders WHERE id=order_ids[5]);
 ASSERT NOT EXISTS(SELECT 1 FROM floor_private.fnb_shift_order_events722 WHERE order_id=order_ids[5]);
 ASSERT (SELECT count(*)=12 FROM floor_private.fnb_shift_intents722 WHERE actor=(f->>'actor')::uuid);
 ASSERT NOT has_table_privilege('authenticated','public.fnb_cashier_shifts','UPDATE');
 ASSERT NOT has_table_privilege('authenticated','floor_private.fnb_shift_intents722','SELECT');
 ASSERT NOT has_function_privilege('service_role','public.fnb_close_shift(uuid,bigint,text,text)','EXECUTE');
 ASSERT NOT has_function_privilege('authenticated','floor_private.fnb_cash_event_gate_v1(uuid)','EXECUTE');
 SELECT fixture INTO STRICT prior FROM floor_private.fnb720_fixture;
 ASSERT (SELECT status='pending' AND subtotal_vnd=5000 FROM public.fnb_orders WHERE id=(prior->>'order')::uuid);
 ASSERT (SELECT on_hand=10 FROM public.fnb_ingredients WHERE id=(prior->>'ingredient')::uuid);
 ASSERT (SELECT count(*)=2 FROM public.payment_settlements WHERE bank_transaction_id IN((prior->>'bank')::uuid,(prior->>'bad_bank')::uuid));
 ASSERT EXISTS(SELECT 1 FROM public.payment_settlements WHERE bank_transaction_id=(prior->>'bank')::uuid AND outcome='flagged_not_pending' AND reason LIKE 'column "old_status" is of type%');
 ASSERT NOT EXISTS(SELECT 1 FROM floor_private.fnb_shift_order_events722 WHERE order_id=(prior->>'order')::uuid),'no historical admission backfill';
 ASSERT NOT EXISTS(SELECT 1 FROM pg_stat_activity WHERE datname=current_database() AND state='idle in transaction' AND pid<>pg_backend_pid());
END $$;
SELECT 'FNB723_COMMITTED_SHIFT_MEMBERSHIP_STOCK_RECEIPTS_PRIMARY_BOUNDARY_FAILED720_PRESERVED';
SELECT p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid)) FROM pg_proc p WHERE proname IN('fnb_open_shift','fnb_close_shift','fnb_get_shift_report','fnb_mark_paid','fnb_cancel_order','fnb_settle_bank_paid','fnb_create_comp_order') ORDER BY 1;
ROLLBACK;
